const svgNS = "http://www.w3.org/2000/svg";

function SVGCanvasOfSize(width, height, children) {
  var canvas = document.createElementNS(svgNS, "svg");
  canvas.setAttributeNS(null, "width", width);
  canvas.setAttributeNS(null, "height", height);
  canvas.setAttributeNS(null, "viewBox", "0 0 " + width + " " + height);
  // These icons are decorative: the surrounding control's text label provides
  // the accessible name. Hide them from assistive tech and keep them out of
  // the tab order (some browsers make inline SVGs focusable).
  canvas.setAttributeNS(null, "aria-hidden", "true");
  canvas.setAttributeNS(null, "focusable", "false");
  if (children != null) {
    var childEnumerator = (parent, children) => {
      children.forEach((child) => {
        var kind = child.kind;
        var element = document.createElementNS(svgNS, kind);
        parent.appendChild(element);

        var attributes = child.attributes;
        if (attributes != null) {
          for (var key in attributes) {
            var value = attributes[key];
            element.setAttributeNS(null, key, value);
          }
        }
        var descendents = child.children;
        if (descendents != null) {
          childEnumerator(element, descendents);
        }
      });
    };
    childEnumerator(canvas, children);
  }
  return canvas;
}

// Monotonic counter used to namespace the internal IDs of SVGs built from
// markup, so the same logo can appear multiple times in the document (e.g. the
// Creator logo in the menu trigger AND in the tool-switcher list) without its
// gradient / clipPath IDs colliding. See SVGFromMarkup.
var gSVGMarkupInstanceCounter = 0;

// Rewrites every id="..." in the SVG and every reference to it
// (url(#...), href="#...", xlink:href="#...") with an instance-unique suffix,
// so multiple copies of the same markup can coexist in one document without
// duplicate IDs breaking url(#...) resolution. Only same-document fragment
// references (those starting with "#") are touched.
function UniquifySVGIds(root, suffix) {
  // querySelectorAll searches descendants only, so include the root element
  // itself in the set of id-bearing elements.
  var idElements = [root].concat(
    Array.prototype.slice.call(root.querySelectorAll("[id]")));
  // Collect the ids declared in this SVG so we only rewrite references that
  // actually point inside it (leaving any unrelated external refs alone).
  var idMap = {};
  for (var i = 0; i < idElements.length; i++) {
    var declaredId = idElements[i].id;
    if (declaredId != null && declaredId.length > 0) {
      idMap[declaredId] = declaredId + suffix;
    }
  }
  // Apply the renames.
  for (var j = 0; j < idElements.length; j++) {
    var el = idElements[j];
    if (el.id != null && idMap[el.id] != null) {
      el.id = idMap[el.id];
    }
  }
  // Rewrite references on every element (including root) to the renamed ids.
  var refElements = root.querySelectorAll("*");
  var rewriteOne = function (element) {
    var attrs = element.attributes;
    if (attrs == null) { return; }
    for (var k = 0; k < attrs.length; k++) {
      var attr = attrs[k];
      var val = attr.value;
      if (val == null || val.indexOf("#") === -1) { continue; }
      // Handle both url(#id) (fill/stroke/clip-path/mask/filter/...) and bare
      // fragment refs (href / xlink:href).
      var rewritten = val.replace(/url\(#([^)\s]+)\)/g, function (full, id) {
        return idMap[id] != null ? "url(#" + idMap[id] + ")" : full;
      });
      if (val.charAt(0) === "#") {
        var bareId = val.slice(1);
        if (idMap[bareId] != null) {
          rewritten = "#" + idMap[bareId];
        }
      }
      if (rewritten !== val) {
        attr.value = rewritten;
      }
    }
  };
  rewriteOne(root);
  for (var m = 0; m < refElements.length; m++) {
    rewriteOne(refElements[m]);
  }
}

// Builds an SVG element from raw markup. Used for multi-gradient brand
// artwork (the Airtime tool logos) that is impractical to express through
// SVGCanvasOfSize's path-list notation.
//
// SECURITY: `markup` MUST be a trusted, static, developer-authored string
// (it is parsed via template.innerHTML, a DOM-injection surface). NEVER pass
// user- or network-provided markup here. All current callers pass hard-coded
// literals defined in this file.
function SVGFromMarkup(markup, width, height) {
  var template = document.createElement("template");
  template.innerHTML = markup.trim();
  var svg = template.content.firstChild;
  // Dev guard: enforce the trusted-static-<svg> contract. Catches a caller
  // accidentally feeding non-<svg> (e.g. unexpected text/nodes from untrusted
  // input) before it reaches the DOM.
  if (svg == null || svg.nodeName == null
      || svg.nodeName.toLowerCase() !== "svg") {
    console.error("SVGFromMarkup expects trusted static <svg> markup; got:",
      svg);
    return svg;
  }
  // The same logo is inserted in multiple places simultaneously, so namespace
  // its internal IDs (gradients/clipPaths like tl_cre_clip) per instance and
  // rewrite url(#...) / href="#..." references to match. Without this,
  // duplicate DOM IDs make url(#...) references resolve to the wrong (or no)
  // element, breaking gradients and clip paths.
  gSVGMarkupInstanceCounter += 1;
  UniquifySVGIds(svg, "_i" + gSVGMarkupInstanceCounter);
  // These brand logos are decorative: the adjacent text label provides the
  // accessible name, so hide the SVG from assistive tech and keep it out of
  // the tab order in browsers that make inline SVGs focusable.
  svg.setAttribute("aria-hidden", "true");
  svg.setAttribute("focusable", "false");
  if (width != null) {
    svg.setAttribute("width", width);
  }
  if (height != null) {
    svg.setAttribute("height", height);
  }
  return svg;
}

